-- Additive reviewed reference briefs, stored candidates and independent selection.
-- CLI unavailable: reviewed named SQL follows repository native-MCP migrations.
-- No model activation, generation resume, provider call or second spending ledger.
begin;
alter table public.director_approvals add column reference_evidence jsonb;
create table public.director_reference_candidates(
 id uuid primary key,project_id uuid not null references public.director_projects(id),subject_id text not null check(length(subject_id) between 1 and 160),subject_version integer not null check(subject_version between 1 and 100),asset_id uuid not null,asset_version integer not null check(asset_version>0),origin text not null check(origin in('generated','uploaded')),job_id uuid unique,created_at timestamptz not null default now(),
 foreign key(project_id,asset_id)references public.director_assets(project_id,id),foreign key(project_id,job_id)references public.director_jobs(project_id,id),check((origin='generated'and job_id is not null)or(origin='uploaded'and job_id is null)));
create index director_reference_candidates_project on public.director_reference_candidates(project_id);
alter table public.director_reference_candidates enable row level security;
create policy no_customer_access on public.director_reference_candidates for all to anon,authenticated using(false)with check(false);
revoke all on public.director_reference_candidates from public,anon,authenticated,service_role;
grant select,insert on public.director_reference_candidates to service_role;
create trigger append_only before update or delete on public.director_reference_candidates for each row execute function public.director_reject_mutation();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('director-reference-media','director-reference-media',false,10485760,array['image/png']);

create function public.director_reference_source_current(p_document jsonb,p_version integer)returns boolean language sql immutable security invoker set search_path=''as $$
 select coalesce(p_version between 1 and 50 and p_document->'referenceProduction'->'sources'->(p_version-1)->'version'=to_jsonb(p_version)and public.director_storyboard_source_current(jsonb_set(p_document,'{storyboardHandoff}',jsonb_build_object('sources',p_document->'referenceProduction'->'sources'),true),p_version),false);
$$;
create function public.director_reference_document_valid(p_document jsonb)returns boolean language plpgsql immutable security invoker set search_path=''as $$
declare k text;item jsonb;seen text[]:='{}';
begin
 if jsonb_typeof(p_document)is distinct from'object'or not(p_document ?& array['name','direction','anchor','framing','mustPreserve','acceptanceCriteria'])then return false;end if;
 for k in select jsonb_object_keys(p_document)loop if k not in('name','direction','anchor','framing','mustPreserve','acceptanceCriteria')then return false;end if;end loop;
 foreach k in array array['name','direction','anchor','framing']loop if jsonb_typeof(p_document->k)is distinct from'string'or length(btrim(p_document->>k))<1 or length(p_document->>k)>(case when k='name'then 200 when k='framing'then 2000 when k='anchor'then 4000 else 12000 end)then return false;end if;end loop;
 if jsonb_typeof(p_document->'mustPreserve')is distinct from'array'or jsonb_array_length(p_document->'mustPreserve')>60 or jsonb_typeof(p_document->'acceptanceCriteria')is distinct from'array'or jsonb_array_length(p_document->'acceptanceCriteria')not between 1 and 40 then return false;end if;
 for item in select value from jsonb_array_elements(p_document->'mustPreserve')loop if jsonb_typeof(item)is distinct from'string'or length(btrim(item#>>'{}'))not between 1 and 4000 then return false;end if;end loop;
 for item in select value from jsonb_array_elements(p_document->'acceptanceCriteria')loop if jsonb_typeof(item)is distinct from'object'or not(item ?& array['id','requirement','evidence','failureCondition'])or coalesce(item->>'id','')!~'^[A-Za-z][A-Za-z0-9_-]{0,79}$'or item->>'id'=any(seen)then return false;end if;seen=array_append(seen,item->>'id');for k in select jsonb_object_keys(item)loop if k not in('id','requirement','evidence','failureCondition')then return false;end if;end loop;foreach k in array array['requirement','evidence','failureCondition']loop if jsonb_typeof(item->k)is distinct from'string'or length(btrim(item->>k))not between 1 and 4000 then return false;end if;end loop;end loop;return true;
exception when invalid_parameter_value then return false;
end $$;
create function public.director_reference_candidate_valid(p_project_id uuid,p_candidate_id uuid,p_subject_id text,p_subject_version integer,p_asset_id uuid,p_asset_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare c public.director_reference_candidates;a public.director_assets;
begin
 select x.*into c from public.director_reference_candidates x where x.id=p_candidate_id and x.project_id=p_project_id and x.subject_id=p_subject_id and x.subject_version=p_subject_version and x.asset_id=p_asset_id and x.asset_version=p_asset_version;
 select x.*into a from public.director_assets x where x.id=c.asset_id and x.project_id=p_project_id;
 return coalesce(c.id is not null and a.id is not null and a.metadata->'version'=to_jsonb(p_asset_version)and a.metadata->>'mime' in('image/png','image/jpeg','image/webp')and coalesce(a.metadata->>'checksum','')~'^[a-f0-9]{64}$'and length(a.storage_key)>0,false);
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end $$;
create function public.director_reference_subject_current(p_project_id uuid,p_document jsonb,p_subject_id text,p_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare subject jsonb;snapshot jsonb;script jsonb;binding jsonb;identity jsonb;selection jsonb;a public.director_artifacts;ap public.director_approvals;n integer;
begin
 if p_version is null or p_version not between 1 and 100 or jsonb_typeof(p_document->'referenceProduction'->'subjects')is distinct from'array'then return false;end if;
 select count(*),min(s.value::text)::jsonb into n,subject from jsonb_array_elements(p_document->'referenceProduction'->'subjects')s where s.value->>'id'=p_subject_id;if n<>1 or subject->'currentVersion'is distinct from to_jsonb(p_version)or subject->>'kind'not in('character_identity','character_look','location')or subject->>'id'is distinct from(case subject->>'kind'when'character_identity'then'identity:'when'character_look'then'look:'else'location:'end)||(subject->>'sourceId')then return false;end if;
 select count(*),min(v.value::text)::jsonb into n,snapshot from jsonb_array_elements(subject->'versions')v where v.value->'version'=to_jsonb(p_version);if n<>1 or jsonb_typeof(snapshot->'sourceVersion')is distinct from'number'or(snapshot->>'sourceVersion')::numeric<>trunc((snapshot->>'sourceVersion')::numeric)or not public.director_reference_source_current(p_document,(snapshot->>'sourceVersion')::integer)or not public.director_reference_document_valid(snapshot->'document')then return false;end if;
 select v.value->'document'into script from jsonb_array_elements(p_document->'screenplay'->'versions')v where v.value->'version'=p_document->'screenplay'->'currentVersion';
 if not exists(select 1 from jsonb_array_elements(case when subject->>'kind'='location'then script->'scenes'else script->'characters'end)e where e.value->'id'=subject->'sourceId')then return false;end if;
 if subject->>'kind'<>'character_look'then return snapshot->'identityBinding'='null'::jsonb;end if;binding=snapshot->'identityBinding';if jsonb_typeof(binding)is distinct from'object'or binding->>'subjectId'is distinct from'identity:'||(subject->>'sourceId')or jsonb_typeof(binding->'subjectVersion')is distinct from'number'or jsonb_typeof(binding->'selectionVersion')is distinct from'number'or jsonb_typeof(binding->'assetVersion')is distinct from'number'then return false;end if;
 select s.value into identity from jsonb_array_elements(p_document->'referenceProduction'->'subjects')s where s.value->>'id'=binding->>'subjectId';if identity->'currentVersion'is distinct from binding->'subjectVersion'or not public.director_reference_subject_current(p_project_id,p_document,binding->>'subjectId',(binding->>'subjectVersion')::integer)then return false;end if;
 select s.value into selection from jsonb_array_elements(p_document->'referenceProduction'->'selections')with ordinality s(value,ordinality)where s.value->>'subjectId'=binding->>'subjectId'order by s.ordinality desc limit 1;
 if selection->'version'is distinct from binding->'selectionVersion'or selection->'subjectVersion'is distinct from binding->'subjectVersion'or selection->'assetId'is distinct from binding->'assetId'or selection->'assetVersion'is distinct from binding->'assetVersion'or not public.director_reference_candidate_valid(p_project_id,(selection->>'candidateId')::uuid,binding->>'subjectId',(binding->>'subjectVersion')::integer,(binding->>'assetId')::uuid,(binding->>'assetVersion')::integer)then return false;end if;
 select x.*into a from public.director_artifacts x where x.project_id=p_project_id and x.logical_key='reference_selection:'||(binding->>'subjectId')and x.kind='reference_selection'and x.version=(binding->>'selectionVersion')::integer;if a.id is null or a.content is distinct from selection then return false;end if;select x.*into ap from public.director_approvals x where x.project_id=p_project_id and x.artifact_id=a.id order by x.ordinal desc limit 1;
 return coalesce(ap.decision='approved'and ap.reference_evidence->'acknowledgeReferenceReview'='true'::jsonb and ap.actor_id=(select p.owner_id from public.director_projects p where p.id=p_project_id)and public.director_reference_direction_approved(p_project_id,p_document,binding->>'subjectId',(binding->>'subjectVersion')::integer),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;
create function public.director_reference_direction_approved(p_project_id uuid,p_document jsonb,p_subject_id text,p_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare a public.director_artifacts;ap public.director_approvals;subject jsonb;snapshot jsonb;
begin
 if not public.director_storyboard_prerequisites_approved(p_project_id)or not public.director_reference_subject_current(p_project_id,p_document,p_subject_id,p_version)then return false;end if;select s.value into subject from jsonb_array_elements(p_document->'referenceProduction'->'subjects')s where s.value->>'id'=p_subject_id;select v.value into snapshot from jsonb_array_elements(subject->'versions')v where v.value->'version'=to_jsonb(p_version);
 select x.*into a from public.director_artifacts x where x.project_id=p_project_id and x.logical_key='reference_brief:'||p_subject_id and x.kind='reference_brief'and x.version=p_version;if a.id is null or a.content is distinct from jsonb_build_object('subjectId',p_subject_id,'kind',subject->'kind','sourceId',subject->'sourceId')||snapshot then return false;end if;select x.*into ap from public.director_approvals x where x.project_id=p_project_id and x.artifact_id=a.id order by x.ordinal desc limit 1;return coalesce(ap.decision='approved'and ap.actor_id=(select p.owner_id from public.director_projects p where p.id=p_project_id),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;
create function public.director_reference_selection_current(p_project_id uuid,p_document jsonb,p_subject_id text,p_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare selection jsonb;subject jsonb;
begin
 select s.value into selection from jsonb_array_elements(p_document->'referenceProduction'->'selections')with ordinality s(value,ordinality)where s.value->>'subjectId'=p_subject_id order by s.ordinality desc limit 1;if selection is null or selection->'version'is distinct from to_jsonb(p_version)or selection->'review'->'criteriaAcknowledged'is distinct from'true'::jsonb then return false;end if;
 select s.value into subject from jsonb_array_elements(p_document->'referenceProduction'->'subjects')s where s.value->>'id'=p_subject_id;return coalesce(selection->'subjectVersion'=subject->'currentVersion'and public.director_reference_direction_approved(p_project_id,p_document,p_subject_id,(selection->>'subjectVersion')::integer)and public.director_reference_candidate_valid(p_project_id,(selection->>'candidateId')::uuid,p_subject_id,(selection->>'subjectVersion')::integer,(selection->>'assetId')::uuid,(selection->>'assetVersion')::integer),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;

-- Keep legacy helpers exact; only new reference keys receive new currentness.
do $$declare definition text;anchor text:='public.director_artifact_is_current(';begin definition=pg_get_functiondef('public.director_artifact_is_current(uuid,uuid)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'reference_artifact_baseline_mismatch';end if;execute replace(definition,anchor,'public.director_reference_legacy_artifact_current(');end $$;
create or replace function public.director_artifact_is_current(p_project_id uuid,p_artifact_id uuid)returns boolean language plpgsql security invoker set search_path=''as $$
declare a public.director_artifacts;document jsonb;subject jsonb;snapshot jsonb;selection jsonb;
begin
 select x.*into a from public.director_artifacts x where x.project_id=p_project_id and x.id=p_artifact_id;if a.id is null then return false;end if;
 if left(a.logical_key,16)='reference_brief:'or left(a.logical_key,20)='reference_selection:'or a.kind in('reference_brief','reference_selection')then select p.brief||'{}'::jsonb into document from public.director_projects p where p.id=p_project_id;
 if left(a.logical_key,16)='reference_brief:'and a.kind='reference_brief'then if not public.director_reference_subject_current(p_project_id,document,substr(a.logical_key,17),a.version)then return false;end if;select s.value into subject from jsonb_array_elements(document->'referenceProduction'->'subjects')s where s.value->>'id'=substr(a.logical_key,17);select v.value into snapshot from jsonb_array_elements(subject->'versions')v where v.value->'version'=to_jsonb(a.version);return a.content=jsonb_build_object('subjectId',subject->'id','kind',subject->'kind','sourceId',subject->'sourceId')||snapshot;
 elsif left(a.logical_key,20)='reference_selection:'and a.kind='reference_selection'then select s.value into selection from jsonb_array_elements(document->'referenceProduction'->'selections')s where s.value->'version'=to_jsonb(a.version);return coalesce(public.director_reference_selection_current(p_project_id,document,substr(a.logical_key,21),a.version)and a.content=selection,false);else return false;end if;end if;return public.director_reference_legacy_artifact_current(p_project_id,p_artifact_id);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;
create function public.director_reference_review_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;a public.director_artifacts;
begin select x.*into p from public.director_projects x where x.id=new.project_id for update;select x.*into a from public.director_artifacts x where x.id=new.artifact_id and x.project_id=p.id;if a.kind not in('reference_brief','reference_selection')then if new.reference_evidence is not null then raise exception'reference_evidence_invalid';end if;return new;end if;if new.actor_id is distinct from p.owner_id then raise exception'not_project_owner';end if;if new.decision='approved'and(new.reference_evidence->'projectVersion'is distinct from p.brief->'version'or new.reference_evidence->>'archiveHash'is distinct from encode(sha256(convert_to((p.brief->'referenceProduction')::text,'UTF8')),'hex')or not public.director_storyboard_prerequisites_approved(p.id)or not public.director_artifact_is_current(p.id,a.id)or a.kind='reference_selection'and new.reference_evidence->'acknowledgeReferenceReview'is distinct from'true'::jsonb)then raise exception'reference_review_required';end if;return new;end $$;
create trigger reference_review_guard before insert on public.director_approvals for each row execute function public.director_reference_review_guard();
create function public.director_approve_reference(p_actor_id uuid,p_project_id uuid,p_expected_version integer,p_artifact_id text,p_artifact_version integer,p_ack_reference_review boolean,p_decision text)returns jsonb language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;a public.director_artifacts;ap public.director_approvals;e jsonb;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_decision is null or p_decision not in('approved','rejected','revoked')or p_artifact_version is null or p_artifact_version<1 then raise exception'reference_review_invalid';end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)then raise exception'reference_review_stale';end if;select x.*into a from public.director_artifacts x where x.project_id=p.id and x.logical_key=p_artifact_id and x.version=p_artifact_version and x.kind in('reference_brief','reference_selection');if a.id is null then raise exception'reference_artifact_missing';end if;e=case when p_decision='approved'then jsonb_build_object('projectVersion',p_expected_version,'archiveHash',encode(sha256(convert_to((p.brief->'referenceProduction')::text,'UTF8')),'hex'),'acknowledgeReferenceReview',p_ack_reference_review)else null end;insert into public.director_approvals(project_id,artifact_id,actor_id,decision,reference_evidence)values(p.id,a.id,p_actor_id,p_decision,e)returning*into ap;return jsonb_build_object('id',ap.id,'projectId',p.id,'artifactId',p_artifact_id,'version',p_artifact_version,'decision',p_decision,'actorId',p_actor_id,'createdAt',ap.created_at);end $$;

create function public.director_reference_candidate_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;a public.director_assets;j public.director_jobs;q public.director_proposals;endpoint text;subject jsonb;g jsonb;
begin select x.*into p from public.director_projects x where x.id=new.project_id for update;select x.*into a from public.director_assets x where x.id=new.asset_id and x.project_id=p.id for update;select s.value into subject from jsonb_array_elements(p.brief->'referenceProduction'->'subjects')s where s.value->>'id'=new.subject_id;if a.id is null or a.metadata->>'id'is distinct from a.id::text or a.metadata->>'projectId'is distinct from p.id::text or a.metadata->>'storageKey'is distinct from a.storage_key or left(a.storage_key,length(p.owner_id::text||'/'||p.id::text||'/'))is distinct from p.owner_id::text||'/'||p.id::text||'/'or not exists(select 1 from jsonb_array_elements(subject->'versions')v where v.value->'version'=to_jsonb(new.subject_version))or a.metadata->'version'is distinct from to_jsonb(new.asset_version)or a.metadata->>'mime'not in('image/png','image/jpeg','image/webp')or coalesce(a.metadata->>'checksum','')!~'^[a-f0-9]{64}$'or length(a.storage_key)<1 or not(case subject->>'kind'when'character_identity'then a.metadata->>'role'in('character_identity','shot_reference')when'character_look'then a.metadata->>'role'in('wardrobe','visual_style','character_identity','shot_reference')when'location'then a.metadata->>'role'in('location','shot_reference')else false end)then raise exception'reference_candidate_asset_invalid';end if;
 if new.origin='uploaded'then if a.metadata ? 'generated'or a.metadata->>'bucket'='director-reference-media'or new.job_id is not null then raise exception'reference_candidate_origin_invalid';end if;return new;end if;
 select x.*into j from public.director_jobs x where x.id=new.job_id and x.project_id=p.id;select x.*into q from public.director_proposals x where x.id=j.proposal_id and x.project_id=p.id;select x.registry_snapshot->>'endpoint'into endpoint from public.director_quote_records x where x.proposal_id=q.id and x.project_id=p.id;g=a.metadata->'generated';
 if j.id is null or j.status is distinct from'completed'or j.provider_request_id is null or q.id is null or q.payload_hash is distinct from j.payload_hash or not exists(select 1 from public.director_artifacts ar where ar.project_id=p.id and ar.id=q.artifact_id and ar.kind='reference_brief'and ar.logical_key='reference_brief:'||new.subject_id and ar.version=new.subject_version)or a.metadata->>'mime'is distinct from'image/png'or a.metadata->>'bucket'is distinct from'director-reference-media'or jsonb_typeof(a.metadata->'size')is distinct from'number'or(a.metadata->>'size')::numeric not between 1 and 10485760 or g is distinct from jsonb_build_object('jobId',j.id,'requestId',j.provider_request_id,'endpoint',endpoint,'payloadHash',j.payload_hash,'subjectId',new.subject_id,'subjectVersion',new.subject_version)or not exists(select 1 from public.director_audit_events e where e.project_id=p.id and e.event_type='job_provider_output'and e.details->>'job_id'=j.id::text and jsonb_typeof(e.details->'output'->'images')='array'and jsonb_array_length(e.details->'output'->'images')=1 and e.details->'output'->'images'->0->>'url'~'^https://([A-Za-z0-9-]+\.)*fal\.media/')then raise exception'reference_generated_provenance_invalid';end if;return new;end $$;
create trigger reference_candidate_guard before insert on public.director_reference_candidates for each row execute function public.director_reference_candidate_guard();
-- Once a stored image has candidate provenance, its content identity cannot be
-- changed in place. A replacement image requires a new asset and human review.
create function public.director_reference_asset_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare k text;
begin if not exists(select 1 from public.director_reference_candidates c where c.asset_id=old.id and c.project_id=old.project_id)then if TG_OP='DELETE'then return old;end if;return new;end if;if TG_OP='DELETE'then raise exception'reference_asset_immutable';end if;if new.project_id is distinct from old.project_id or new.kind is distinct from old.kind or new.storage_key is distinct from old.storage_key then raise exception'reference_asset_immutable';end if;foreach k in array array['id','projectId','storageKey','version','mime','role','checksum','size','bucket','generated']loop if new.metadata->k is distinct from old.metadata->k then raise exception'reference_asset_immutable';end if;end loop;return new;end $$;
create trigger reference_asset_guard before update or delete on public.director_assets for each row execute function public.director_reference_asset_guard();
create function public.director_register_reference_candidate(p_actor_id uuid,p_project_id uuid,p_candidate jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;c public.director_reference_candidates;v public.director_reference_candidates;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_candidate->>'projectId'is distinct from p.id::text or jsonb_typeof(p_candidate->'subjectVersion')is distinct from'number'or(p_candidate->>'subjectVersion')::numeric<>trunc((p_candidate->>'subjectVersion')::numeric)or jsonb_typeof(p_candidate->'assetVersion')is distinct from'number'or(p_candidate->>'assetVersion')::numeric<>trunc((p_candidate->>'assetVersion')::numeric)then raise exception'reference_candidate_invalid';end if;v.id=(p_candidate->>'id')::uuid;v.project_id=p.id;v.subject_id=p_candidate->>'subjectId';v.subject_version=(p_candidate->>'subjectVersion')::integer;v.asset_id=(p_candidate->>'assetId')::uuid;v.asset_version=(p_candidate->>'assetVersion')::integer;v.origin=p_candidate->>'origin';v.job_id=(p_candidate->>'jobId')::uuid;select x.*into c from public.director_reference_candidates x where x.id=v.id or v.job_id is not null and x.job_id=v.job_id;if c.id is not null then if to_jsonb(c)-'created_at'is distinct from to_jsonb(v)-'created_at'then raise exception'reference_candidate_conflict';end if;else insert into public.director_reference_candidates(id,project_id,subject_id,subject_version,asset_id,asset_version,origin,job_id)values(v.id,v.project_id,v.subject_id,v.subject_version,v.asset_id,v.asset_version,v.origin,v.job_id)returning*into c;end if;return jsonb_build_object('id',c.id,'projectId',c.project_id,'subjectId',c.subject_id,'subjectVersion',c.subject_version,'assetId',c.asset_id,'assetVersion',c.asset_version,'origin',c.origin,'jobId',c.job_id,'createdAt',to_char(c.created_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));end $$;

create function public.director_reference_quote_valid(p_project_id uuid,p_document jsonb,p_quote jsonb,p_payload jsonb,p_endpoint text)returns boolean language plpgsql security invoker set search_path=''as $$
declare subject jsonb;snapshot jsonb;source jsonb;expected jsonb;identity public.director_assets;url text;
begin
 if left(p_quote->>'artifactId',16)<>'reference_brief:'then return false;end if;select s.value into subject from jsonb_array_elements(p_document->'referenceProduction'->'subjects')s where 'reference_brief:'||(s.value->>'id')=p_quote->>'artifactId';select v.value into snapshot from jsonb_array_elements(subject->'versions')v where v.value->'version'=subject->'currentVersion';if p_quote->'artifactVersion'is distinct from snapshot->'version'or not public.director_reference_direction_approved(p_project_id,p_document,subject->>'id',(snapshot->>'version')::integer)then return false;end if;select s.value into source from jsonb_array_elements(p_document->'referenceProduction'->'sources')s where s.value->'version'=snapshot->'sourceVersion';expected=jsonb_build_object('subjectId',subject->'id','subjectVersion',snapshot->'version','sourceVersion',snapshot->'sourceVersion','inputSignature',source->'inputSignature','document',snapshot->'document','identityBinding',snapshot->'identityBinding','prompt',p_payload->'prompt');if p_quote->'referenceBinding'is distinct from expected or jsonb_typeof(p_payload->'prompt')is distinct from'string'or length(btrim(p_payload->>'prompt'))<1 or p_payload->'image_size'is distinct from'{"width":1024,"height":1024}'::jsonb or p_payload->>'output_format'is distinct from'png'or p_payload->'sync_mode'is distinct from'false'::jsonb or p_payload->'enable_safety_checker'is distinct from'true'::jsonb then return false;end if;
 if subject->>'kind'='character_look'then
 if p_quote->>'task'is distinct from'reference_look'or p_endpoint is distinct from'bytedance/seedream/v5/pro/edit'or p_payload->'num_images'is distinct from'1'::jsonb or jsonb_typeof(p_payload->'image_urls')is distinct from'array'or jsonb_array_length(p_payload->'image_urls')<>1 then return false;end if;select x.*into identity from public.director_assets x where x.project_id=p_project_id and x.id=(snapshot->'identityBinding'->>'assetId')::uuid;url=p_payload->'image_urls'->>0;return coalesce(identity.id is not null and url~'^https://[A-Za-z0-9.-]+/storage/v1/object/sign/'and position('/storage/v1/object/sign/'||coalesce(identity.metadata->>'bucket','director-media')||'/'||identity.storage_key||'?' in url)>0,false);
 end if;
 return coalesce(p_quote->>'task'='reference_image'and(subject->>'kind')in('character_identity','location')and((p_endpoint='fal-ai/flux-2-pro'and not(p_payload ? 'num_images')and p_payload->>'safety_tolerance'='2')or(p_endpoint='fal-ai/flux-2/klein/9b'and p_payload->'num_images'='1'::jsonb and p_payload->'num_inference_steps'='4'::jsonb))and not(p_payload ? 'image_urls')and not(p_payload ? 'image_url'),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;
-- Reference briefs are reviewed preproduction targets; selected images are never
-- media-generation targets. Legacy media paths keep their previous predicates.
do $$declare definition text;anchor text;begin
 anchor='if project.id is null or project.owner_id is null then return false; end if;';definition=pg_get_functiondef('public.director_document_approval_ready(uuid,text,integer)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'reference_approval_ready_baseline_mismatch';end if;execute replace(definition,anchor,anchor||' if left(p_logical_key,16)=''reference_brief:''then return public.director_reference_direction_approved(project.id,project.brief,substr(p_logical_key,17),p_version);end if;if left(p_logical_key,20)=''reference_selection:''then return false;end if;');
 anchor='if a.kind in(''shot_contract'',''storyboard_sequence'')';definition=pg_get_functiondef('public.director_storyboard_media_ready(uuid,uuid)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'reference_storyboard_gate_baseline_mismatch';end if;execute replace(definition,anchor,'if a.kind=''reference_brief''and left(a.logical_key,16)=''reference_brief:''then return public.director_reference_direction_approved(p.id,p.brief,substr(a.logical_key,17),a.version);end if;if a.kind=''reference_selection''or left(a.logical_key,20)=''reference_selection:''then return false;end if;'||anchor);
 anchor='if not public.director_storyboard_media_ready(p.id,a.id)then';definition=pg_get_functiondef('public.director_persist_quote(uuid,uuid,integer,uuid,text,jsonb,jsonb)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'reference_quote_baseline_mismatch';end if;execute replace(definition,anchor,'if a.kind=''reference_brief''and(not public.director_reference_quote_valid(p.id,p.brief,p_quote,p_payload,m.endpoint)or not coalesce(m.capabilities->''tasks'' @>jsonb_build_array(p_quote->>''task''),false))then raise exception ''reference_quote_invalid'';end if;'||anchor);
 definition=pg_get_functiondef('public.director_authorize_quote(uuid,uuid,integer,uuid,text,bigint,bigint,timestamptz)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'reference_authorize_baseline_mismatch';end if;execute replace(definition,anchor,'if a.kind=''reference_brief''and(not public.director_reference_quote_valid(p.id,p.brief,saved.quote,q.payload,m.endpoint)or not coalesce(m.capabilities->''tasks'' @>jsonb_build_array(saved.quote->>''task''),false))then raise exception ''reference_quote_invalid'';end if;'||anchor);
end $$;
create function public.director_reference_job_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;q public.director_proposals;a public.director_artifacts;s public.director_quote_records;m public.director_models;
begin if TG_OP='UPDATE'then if not(old.status='reserved'and new.status='submitted')then return new;end if;end if;select x.*into p from public.director_projects x where x.id=new.project_id for update;select x.*into q from public.director_proposals x where x.id=new.proposal_id and x.project_id=p.id;select x.*into a from public.director_artifacts x where x.id=q.artifact_id and x.project_id=p.id;if a.kind not in('reference_brief','reference_selection')then return new;end if;select x.*into s from public.director_quote_records x where x.proposal_id=q.id and x.project_id=p.id;select x.*into m from public.director_models x where x.id=q.model_id;if a.kind='reference_selection'or s.quote_id is null or not coalesce(m.capabilities->'tasks' @>jsonb_build_array(s.quote->>'task'),false)or not public.director_reference_quote_valid(p.id,p.brief,s.quote,q.payload,m.endpoint)then raise exception'reference_job_scope_changed';end if;return new;end $$;
create trigger reference_job_insert_guard before insert on public.director_jobs for each row execute function public.director_reference_job_guard();
create trigger reference_job_dispatch_guard before update of status on public.director_jobs for each row execute function public.director_reference_job_guard();

create function public.director_reference_archive_guard()returns trigger language plpgsql security invoker set search_path=''as $$
begin if new.brief->'referenceProduction'is distinct from old.brief->'referenceProduction'and current_setting('director.reference_write',true)is distinct from new.id::text then raise exception'reference_guarded_save_required';end if;return new;end $$;
create trigger reference_archive_guard before update of brief on public.director_projects for each row execute function public.director_reference_archive_guard();
create function public.director_save_reference_production(p_actor_id uuid,p_project_id uuid,p_expected_version integer,p_expected_approval_id uuid,p_document jsonb,p_artifacts jsonb)returns void language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;previous text;latest uuid;archive jsonb:=p_document->'referenceProduction';old_archive jsonb;subject jsonb;old_subject jsonb;snapshot jsonb;selection jsonb;source jsonb;n integer;i integer;ordinal integer;
begin
 select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)or p_document->'version'is distinct from to_jsonb(p_expected_version+1)then raise exception'reference_save_stale';end if;select a.id into latest from public.director_approvals a where a.project_id=p.id order by a.ordinal desc limit 1;if latest is distinct from p_expected_approval_id then raise exception'reference_approval_changed';end if;
 if not public.director_storyboard_prerequisites_approved(p.id)or p_document-'referenceProduction'-'version'is distinct from p.brief-'referenceProduction'-'version'or jsonb_typeof(archive)is distinct from'object'or jsonb_typeof(archive->'sources')is distinct from'array'or jsonb_array_length(archive->'sources')not between 1 and 50 or jsonb_typeof(archive->'subjects')is distinct from'array'or jsonb_array_length(archive->'subjects')not between 1 and 200 or jsonb_typeof(archive->'selections')is distinct from'array'or jsonb_array_length(archive->'selections')>1000 then raise exception'reference_save_scope_invalid';end if;old_archive=p.brief->'referenceProduction';
 ordinal=0;for source in select value from jsonb_array_elements(archive->'sources')loop ordinal=ordinal+1;if source->'version'is distinct from to_jsonb(ordinal)or jsonb_typeof(source->'inputSignature')is distinct from'string'or length(source->>'inputSignature')not between 1 and 350000 then raise exception'reference_source_invalid';end if;end loop;

 for i in 0..coalesce(jsonb_array_length(old_archive->'sources'),0)-1 loop if archive->'sources'->i is distinct from old_archive->'sources'->i then raise exception'reference_history_invalid';end if;end loop;for i in 0..coalesce(jsonb_array_length(old_archive->'selections'),0)-1 loop if archive->'selections'->i is distinct from old_archive->'selections'->i then raise exception'reference_history_invalid';end if;end loop;
 for old_subject in select value from jsonb_array_elements(coalesce(old_archive->'subjects','[]'::jsonb))loop select s.value into subject from jsonb_array_elements(archive->'subjects')s where s.value->'id'=old_subject->'id';if subject is null or subject->'kind'is distinct from old_subject->'kind'or subject->'sourceId'is distinct from old_subject->'sourceId'then raise exception'reference_history_invalid';end if;for i in 0..jsonb_array_length(old_subject->'versions')-1 loop if subject->'versions'->i is distinct from old_subject->'versions'->i then raise exception'reference_history_invalid';end if;end loop;end loop;
 for subject in select value from jsonb_array_elements(archive->'subjects')loop if coalesce(subject->>'id','')!~'^(identity|look|location):[A-Za-z][A-Za-z0-9_-]{0,79}$'or subject->>'kind'not in('character_identity','character_look','location')or subject->>'id'is distinct from(case subject->>'kind'when'character_identity'then'identity:'when'character_look'then'look:'else'location:'end)||(subject->>'sourceId')or jsonb_typeof(subject->'versions')is distinct from'array'or jsonb_array_length(subject->'versions')not between 1 and 100 or subject->'currentVersion'is distinct from to_jsonb(jsonb_array_length(subject->'versions'))then raise exception'reference_subject_invalid';end if;ordinal=0;for snapshot in select value from jsonb_array_elements(subject->'versions')loop ordinal=ordinal+1;if snapshot->'version'is distinct from to_jsonb(ordinal)or jsonb_typeof(snapshot->'sourceVersion')is distinct from'number'or(snapshot->>'sourceVersion')::numeric not between 1 and jsonb_array_length(archive->'sources')or(snapshot->>'sourceVersion')::numeric<>trunc((snapshot->>'sourceVersion')::numeric)or not public.director_reference_document_valid(snapshot->'document')or subject->>'kind'<>'character_look'and snapshot->'identityBinding'is distinct from'null'::jsonb then raise exception'reference_subject_invalid';end if;end loop;
 select count(*)into n from jsonb_array_elements(archive->'subjects')s where s.value->'id'=subject->'id';if n<>1 then raise exception'reference_subject_invalid';end if;snapshot=subject->'versions'->-1;if not public.director_reference_document_valid(snapshot->'document')or snapshot->'version'is distinct from subject->'currentVersion'or jsonb_typeof(snapshot->'sourceVersion')is distinct from'number'or(snapshot->>'sourceVersion')::numeric not between 1 and 50 or(snapshot->>'sourceVersion')::numeric<>trunc((snapshot->>'sourceVersion')::numeric)or not exists(select 1 from jsonb_array_elements(archive->'sources')s where s.value->'version'=snapshot->'sourceVersion')then raise exception'reference_subject_invalid';end if;end loop;
 i=0;for selection in select value from jsonb_array_elements(archive->'selections')loop i=i+1;if selection->'version'is distinct from to_jsonb(i)then raise exception'reference_selection_invalid';end if;if i>coalesce(jsonb_array_length(old_archive->'selections'),0)and not public.director_reference_selection_current(p.id,p_document,selection->>'subjectId',i)then raise exception'reference_selection_invalid';end if;end loop;
 previous=current_setting('director.reference_write',true);perform set_config('director.reference_write',p.id::text,true);perform public.director_save_project(p_actor_id,p_project_id,p_expected_version,p_document,p_artifacts);perform set_config('director.reference_write',coalesce(previous,''),true);
end $$;
create function public.director_reserve_reference_job(p_actor_id uuid,p_project_id uuid,p_expected_version integer,p_quote_id text,p_authorization_id uuid,p_idempotency_key text)returns public.director_jobs language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;s public.director_quote_records;q public.director_proposals;a public.director_artifacts;w public.director_work_units;j public.director_jobs;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;select x.*into s from public.director_quote_records x where x.quote_id=p_quote_id and x.project_id=p.id and x.actor_id=p_actor_id;select x.*into q from public.director_proposals x where x.id=s.proposal_id and x.project_id=p.id;select x.*into j from public.director_jobs x where x.project_id=p.id and x.idempotency_key=p_idempotency_key;if j.id is not null then if j.proposal_id is distinct from q.id or j.authorization_id is distinct from p_authorization_id then raise exception'idempotency_conflict';end if;return j;end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)then raise exception'reference_save_stale';end if;if s.project_version is distinct from p_expected_version or s.quote->'projectVersion'is distinct from to_jsonb(p_expected_version)then raise exception'reference_quote_stale';end if;select x.*into a from public.director_artifacts x where x.id=q.artifact_id and x.project_id=p.id and x.kind='reference_brief';if a.id is null then raise exception'reference_quote_invalid';end if;select x.*into w from public.director_work_units x where x.project_id=p.id and x.logical_key='reference:'||a.logical_key||':v'||a.version::text;if w.id is null then insert into public.director_work_units(project_id,logical_key,artifact_id)values(p.id,'reference:'||a.logical_key||':v'||a.version::text,a.id)returning*into w;end if;return public.director_reserve_job(p_actor_id,p.id,w.id,q.id,p_authorization_id,p_idempotency_key,q.payload_hash);end $$;
create function public.director_review_reference_job(p_actor_id uuid,p_project_id uuid,p_job_id uuid,p_expected_version integer,p_reason text)returns jsonb language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;j public.director_jobs;q public.director_proposals;r public.director_reviews;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)or p_reason is null or length(btrim(p_reason))not between 5 and 2000 then raise exception'reference_review_invalid';end if;select x.*into j from public.director_jobs x where x.id=p_job_id and x.project_id=p.id;select x.*into q from public.director_proposals x where x.id=j.proposal_id and x.project_id=p.id;if j.status not in('completed','failed')or j.provider_request_id is null or not exists(select 1 from public.director_artifacts a where a.id=q.artifact_id and a.project_id=p.id and a.kind='reference_brief')then raise exception'reference_review_unavailable';end if;insert into public.director_reviews(project_id,job_id,actor_id,verdict,evidence)values(p.id,j.id,p_actor_id,'correction_required',jsonb_build_object('reason',p_reason,'source','explicit_user_review'))returning*into r;return jsonb_build_object('id',r.id,'projectId',p.id,'jobId',j.id,'verdict',r.verdict,'evidence',r.evidence,'createdAt',r.created_at);end $$;
-- All new functions and candidate receipts are available only to trusted server
-- infrastructure. Existing owner checks remain mandatory on every RPC.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and(p.proname like'director_reference_%'or p.proname in('director_approve_reference','director_register_reference_candidate','director_save_reference_production','director_reserve_reference_job','director_review_reference_job'))loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
comment on table public.director_reference_candidates is'Immutable owned stored-image provenance. Candidate registration is not selection, visual approval, rights clearance, invoice settlement or spending consent.';
commit;
